    (ctx.MkGe(x, ctx.MkInt(10)),  "x >= 10"),
    (ctx.MkLe(x, ctx.MkInt(50)),  "x <= 50"),
    (ctx.MkEq(ctx.MkMod(x, ctx.MkInt(2)), ctx.MkInt(0)), "x est pair (x mod 2 = 0)"),
};

