// Exemple guide : maximiser profit = 50x + 80y - x^2 - 2y^2 - xy.
// On minimise l'oppose (convention metaheuristique).
static double ProfitNeg(double[] sol)
{
    double x = sol[0], y = sol[1];
    double profit = 50*x + 80*y - x*x - 2*y*y - x*y;
    return -profit;
}

// Optimum analytique : x=120/7 ~ 17.1429, y=110/7 ~ 15.7143, profit ~ 1057.14
double xOpt = 120.0/7, yOpt = 110.0/7;
double profitOpt = 50*xOpt + 80*yOpt - xOpt*xOpt - 2*yOpt*yOpt - xOpt*yOpt;
Console.WriteLine($"Optimum analytique : x={xOpt:F4}, y={yOpt:F4}, profit={profitOpt:F4}");
Console.WriteLine();

// PSO sur le profit (bornes [0,20])
var psoProfit = new PSO(dim: 2, lb: 0.0, ub: 20.0, f: ProfitNeg, popSize: 30, epochs: 100, seed: 42);
var (solP, fitP, msP) = psoProfit.Solve();
Console.WriteLine($"PSO : x={solP[0]:F4}, y={solP[1]:F4}, profit={-fitP:F4} ({msP:F1} ms)");

// SA sur le même
var saProfit = new SA(dim: 2, lb: 0.0, ub: 20.0, f: ProfitNeg, epochs: 3000, tempInit: 50, alpha: 0.999, stepSize: 3.0, seed: 42);
var (solS, fitS, msS) = saProfit.Solve();
Console.WriteLine($"SA  : x={solS[0]:F4}, y={solS[1]:F4}, profit={-fitS:F4} ({msS:F1} ms)");
Console.WriteLine();
Console.WriteLine($"Concordance avec l'optimum analytique (x={xOpt:F3}, y={yOpt:F3}, profit={profitOpt:F3}) : les metaheuristiques le retrouvent.");

// --- Profit SAISONNIER : quand le metaheuristique devient necessaire ---
// Le profit concave ci-dessus est unimodal : un seul optimum, accessible analytiquement,
// que PSO et SA retrouvent trivialement (une descente de gradient ferait l'affaire).
// Un marche reel est cyclique (saisonnalite). Ajoutons une composante sinusoidale :
//   P(x,y) = 50x + 80y - x^2 - 2y^2 - xy + 120*sin(1.2x)*sin(1.2y)
// Le terme sinusoidal grave un quadrillage de ~15 maxima locaux aux bassins profonds dans
// [0,20]^2. L'optimum n'est plus accessible analytiquement (gradient = 0 = systeme non
// lineaire sans solution fermee), et une descente de gradient resterait coincee dans le
// premier bassin rencontre.
// C'est precisement la que PSO (exploration globale par essaim) et SA (echappement des
// minima locaux par acceptation probabiliste de mouvements defavorables) deviennent
// indispensables - leur capacite distinctive est enfin mise a contribution.
static double ProfitSaisonnierNeg(double[] sol)
{
    double x = sol[0], y = sol[1];
    double baseConcave = 50*x + 80*y - x*x - 2*y*y - x*y;
    double saison = 120.0 * Math.Sin(1.2*x) * Math.Sin(1.2*y);
    return -(baseConcave + saison);
}

Console.WriteLine();
Console.WriteLine("Profit saisonnier (multimodal) - PSO vs SA sur 5 seeds :");
int[] seedsMM = { 0, 42, 123, 456, 789 };
Console.WriteLine($"{"Seed",-6} {"PSO profit",-12} {"SA profit",-12} {"PSO (x,y)",-20} {"SA (x,y)",-20}");
Console.WriteLine(new string('-', 72));
