    var (solS, fitS, _) = new SA (2, 0.0, 20.0, ProfitSaisonnierNeg, 3000, tempInit: 50, alpha: 0.999, stepSize: 3.0, seed: sd).Solve();
    double profP = -fitP, profS = -fitS;
    psoSumMM += profP; saSumMM += profS;
    if (profP > psoBestMM) psoBestMM = profP;
    if (profS > saBestMM) saBestMM = profS;
    string posP = $"({solP[0]:F2}, {solP[1]:F2})";
    string posS = $"({solS[0]:F2}, {solS[1]:F2})";
    Console.WriteLine($"{sd,-6} {profP,-12:F2} {profS,-12:F2} {posP,-20} {posS,-20}");
}
