// Reseau de flot canonique (Cormen et al., chapitre 26) : 4 sommets S, A, B, T.
//   S -> A (10)   A -> T (8)
//   S -> B (5)    B -> T (10)
//   A -> B (3)
//
// Flot max S -> T = 15 (min-cut : la coupe {S} | {A,B,T} vaut S->A(10) + S->B(5) = 15,
// et par le theoreme max-flow/min-cut c'est aussi le flot maximum). L'arete A->B laisse
// A router son excedent vers B puis T : S->A(10) se partage en A->T(8) + A->B(2), et B
// recevant S->B(5) + A->B(2) = 7 les pousse vers B->T (capacite 10). Total arrive a T = 15.
//
// API QuikGraph 2.5.0 : EdmondsKarpMaximumFlowAlgorithm exige que le graphe soit augmente
// de ses aretes residuelles AVANT l'appel a Compute (sinon InvalidOperationException
// "The graph has not been augmented yet"). On instancie donc le ReversedEdgeAugmentorAlgorithm
// separement, on appelle AddReversedEdges(), puis on construit l'algorithme sur le graphe
// augmente. Cleanup final via RemoveReversedEdges() pour ne pas polluer le graphe.

var flowGraph = new BidirectionalGraph<string, STaggedEdge<string, double>>();
flowGraph.AddVertex("S");
flowGraph.AddVertex("A");
flowGraph.AddVertex("B");
flowGraph.AddVertex("T");

void AddFlowEdge(string from, string to, double cap)
{
    flowGraph.AddEdge(new STaggedEdge<string, double>(from, to, cap));
}

AddFlowEdge("S", "A", 10);
AddFlowEdge("S", "B", 5);
AddFlowEdge("A", "T", 8);
AddFlowEdge("B", "T", 10);
AddFlowEdge("A", "B", 3);

Console.WriteLine("Reseau de flot : S, A, B, T");
Console.WriteLine("  Aretes : S->A:10, S->B:5, A->T:8, B->T:10, A->B:3");

EdgeFactory<string, STaggedEdge<string, double>> creeAretesResiduelles =
    (s, t) => new STaggedEdge<string, double>(s, t, 0.0);

// Etape obligatoire : augmenter le graphe des aretes residuelles AVANT l'algorithme.
var augmentor = new ReversedEdgeAugmentorAlgorithm<string, STaggedEdge<string, double>>(
    flowGraph, creeAretesResiduelles);
augmentor.AddReversedEdges();

var maxFlowAlgo = new EdmondsKarpMaximumFlowAlgorithm<string, STaggedEdge<string, double>>(
    flowGraph,
    e => e.Tag,
    creeAretesResiduelles,
    augmentor
);
maxFlowAlgo.Compute("S", "T");

Console.WriteLine();
Console.WriteLine($"Flot maximum S -> T : {maxFlowAlgo.MaxFlow:F2}");
Console.WriteLine("  (Verification min-cut : {S} | {A,B,T} = S->A(10) + S->B(5) = 15)");
Console.WriteLine();
Console.WriteLine("Fin cellule flot max.");

// Cleanup : retirer les aretes residuelles ajoutees pour ne pas polluer le graphe.
augmentor.RemoveReversedEdges();

using QuikGraph.Algorithms.Observers;
Console.WriteLine("Debut cellule grille 5x5...");
// Reseau routier 5x5 : 25 sommets (0,0)..(4,4). Aretes Est-Ouest + Nord-Sud.
// Prong B (#3801) : pour que Dijkstra se distingue de BFS, on donne a chaque arete un
// COUT DE TERRAIN HETEROGENE dans [1.0, 3.0] (1.0 = voie rapide, 3.0 = voie lente), tire
// deterministement (seed 7, RNG terrain distinct du RNG de bruit). Avec des poids
// uniformes (1.0 partout), le plus court chemin = chemin en nombre de sauts (BFS) et
// Dijkstra n'apporte rien ; avec un terrain heterogene, minimiser la somme des couts
// != minimiser le nombre de sauts, et le chemin optimal peut faire un detour par des
// aretes bon marche pour eviter une arete chere — capacite distinctive de Dijkstra.
// Bruit : on supprime en plus 30% des aretes avec seed 42 (reseau incomplet).

int N = 5;
var grille = new BidirectionalGraph<(int, int), STaggedEdge<(int, int), double>>();
var aretesInitiales = new List<((int, int), (int, int), double)>();
var rngTerrain = new Random(7);   // cout de terrain deterministe, distinct du bruit
for (int i = 0; i < N; i++)
{
    for (int j = 0; j < N; j++)
    {
        grille.AddVertex((i, j));
        if (i + 1 < N) aretesInitiales.Add(((i, j), (i + 1, j), 1.0 + rngTerrain.NextDouble() * 2.0));
        if (j + 1 < N) aretesInitiales.Add(((i, j), (i, j + 1), 1.0 + rngTerrain.NextDouble() * 2.0));
    }
}
double bruit = 0.30;
var rng = new Random(42);          // suppression de 30% des aretes
var aretesConservees = aretesInitiales.Where(_ => rng.NextDouble() > bruit).ToList();
foreach (var (src, dst, cout) in aretesConservees)
{
    grille.AddEdge(new STaggedEdge<(int, int), double>(src, dst, cout));
    grille.AddEdge(new STaggedEdge<(int, int), double>(dst, src, cout));
}
int aretesAttendues = aretesInitiales.Count;
int aretesFinales = aretesConservees.Count * 2;
Console.WriteLine($"Reseau 5x5 : {grille.VertexCount} sommets, {aretesFinales}/{aretesAttendues * 2} aretes (apres bruit {bruit:P0}).");

// Plus court chemin (0,0) -> (N-1, N-1) en distance ponderee (Dijkstra)
var start = (0, 0);
var fin = (N - 1, N - 1);
var dijkstraGrille = new DijkstraShortestPathAlgorithm<(int, int), STaggedEdge<(int, int), double>>(
    grille, e => e.Tag
);
// Observateur canonique : enregistre l'arbre des predecesseurs pendant le calcul (condition
// d'optimalite GetDistance(u) + poids(u, v) = GetDistance(v) encapsulee — cf cell 11).
var recGrille = new VertexPredecessorRecorderObserver<(int, int), STaggedEdge<(int, int), double>>();
recGrille.Attach(dijkstraGrille);
dijkstraGrille.Compute(start);
if (dijkstraGrille.TryGetDistance(fin, out double distGrille))
{
    // Reconstruction du chemin via TryGetPath (aretes -> projection en sommets) pour compter
    // les sauts : preuve que le chemin optimal en distance ponderee n'est pas le chemin en
    // nombre de sauts.
    bool okChemin = recGrille.TryGetPath(fin, out var aretesOpt);
    int sauts = okChemin ? aretesOpt.Count() : 0;
    int manhattan = (N - 1) * 2;  // nombre de sauts du chemin direct coin-a-coin
    double coutMoyen = distGrille / Math.Max(1, sauts);
    Console.WriteLine($"Dijkstra {start} -> {fin} : distance ponderee = {distGrille:F2} km, chemin = {sauts} sauts (chemin direct coin-a-coin = {manhattan} sauts).");
    Console.WriteLine($"Cout moyen par arete du chemin optimal : {coutMoyen:F2} km (si le terrain etait uniforme a 1 km, la distance serait egale au nombre de sauts).");
    Console.WriteLine("Le chemin optimal en distance ponderee ne coincide pas avec le chemin en nombre de sauts : Dijkstra pondere, BFS non.");
}
else
{
    Console.WriteLine($"Pas de chemin {start} -> {fin} apres suppression de 30% des aretes. Reconnecter le graphe.");
}
Console.WriteLine("Fin cellule grille 5x5.");

