// Paysage de fitness : sinusoidal module pour creer plusieurs optima locaux.
// f(x) = sin(x) + 0.4*sin(3*x) sur [xmin, xmax]. Plusieurs pics locaux.
double Fitness(double x) => Math.Sin(x) + 0.4 * Math.Sin(3 * x);

