// Exemple guidé 1 : cadre de tournoi (contribution TP, PR #22577)
public record ResultatMatch(string JoueurA, string JoueurB, int VictoiresA, int VictoiresB, int Nuls);
var resultats = new List<ResultatMatch>();

public static int? JoueurAleatoire<TEtat>(IJeuSommeNulle<TEtat> jeu, TEtat etat, Random rng)
{
    var actions = jeu.Actions(etat);          // cases libres
    if (actions.Count == 0) return null;
    return actions[rng.Next(actions.Count)];  // une au hasard
}

public static int? JouerPartie<TEtat>(
    IJeuSommeNulle<TEtat> jeu,
    Func<IJeuSommeNulle<TEtat>, TEtat, int?> fnMax,
    Func<IJeuSommeNulle<TEtat>, TEtat, int?> fnMin)
{
    var etat = jeu.EtatInitial();
    while (!jeu.EstTerminal(etat))
    {
        // À qui le tour ? On choisit la bonne fonction
        var fn = jeu.Joueur(etat) == "MAX" ? fnMax : fnMin;
        int? action = fn(jeu, etat);
        if (action is null) throw new InvalidOperationException("Aucun coup renvoyé.");
        etat = jeu.Resultat(etat, action.Value);   // on joue le coup
    }
    return (int)jeu.Utilite(etat, "MAX");          // +1, 0 ou -1
}

