for (int i = 0; i < nParties; i++)
{
    var etat = jeuNim.EtatInitial();
    string mctsJoueur = i % 2 == 0 ? "MAX" : "MIN";
    while (!jeuNim.EstTerminal(etat))
    {
        int a;
