        else
            a = StrategieOptimaleNim(etat);
        etat = jeuNim.Resultat(etat, a);
    }
    double u = jeuNim.Utilite(etat, mctsJoueur);
    if (u > 0) victoiresMcts++; else if (u == 0) nulles++;
}
