// dim=10, 50 individus, 200 generations, seed 42 -> directement comparable au GA from-scratch.
#r "nuget: GeneticSharp"
using GeneticSharp;

// GeneticSharp expose son generateur aleatoire via IRandomization (branchable). On branche une
// version sempable (seed 42) pour un resultat reproductible, comme le GA from-scratch.
public class SeededRandomization : IRandomization
{
    private readonly Random _rng = new Random(42);
    public int GetInt(int min, int max) => _rng.Next(min, max);
    public int[] GetInts(int length, int min, int max)
    { var a = new int[length]; for (int i = 0; i < length; i++) a[i] = _rng.Next(min, max); return a; }
    public int[] GetUniqueInts(int length, int min, int max)
    { var pool = new List<int>(); for (int v = min; v < max; v++) pool.Add(v);
      var a = new int[length];
      for (int i = 0; i < length && pool.Count > 0; i++) { int idx = _rng.Next(pool.Count); a[i] = pool[idx]; pool.RemoveAt(idx); }
      return a; }
    public float GetFloat() => (float)_rng.NextDouble();
    public float GetFloat(float min, float max) => min + (float)_rng.NextDouble() * (max - min);
    public double GetDouble() => _rng.NextDouble();
    public double GetDouble(double min, double max) => min + _rng.NextDouble() * (max - min);
}
RandomizationProvider.Current = new SeededRandomization();

// Fitness de minimisation generique : GeneticSharp MAXIMISE la fitness -> on renvoie -f.
public class MinFitness : IFitness
{
    public Func<double[],double> F;
    public MinFitness(Func<double[],double> f) { F = f; }
    public double Evaluate(IChromosome c) => -F(((FloatingPointChromosome)c).ToFloatingPoints());
}

// Run GeneticSharp sur une fonction : chromosome binaire 10 genes (64 bits/gene, 10 fractionnels),
// croisement uniforme (gene par gene) + mutation flip-bit (le classique des GA binaires de Holland/Goldberg).
double RunGS(string name, Func<double[],double> f, double lb, double ub)
{
    int[] bits = Enumerable.Repeat(64, 10).ToArray();
    int[] fr   = Enumerable.Repeat(10, 10).ToArray();
    double[] mn = Enumerable.Repeat(lb, 10).ToArray();
    double[] mx = Enumerable.Repeat(ub, 10).ToArray();
    var pop = new Population(50, 50, new FloatingPointChromosome(mn, mx, bits, fr));
    var ga = new GeneticAlgorithm(pop, new MinFitness(f),
        new TournamentSelection(3), new UniformCrossover(), new FlipBitMutation());
    ga.Termination = new GenerationNumberTermination(200);
    ga.CrossoverProbability = 0.9f;
    ga.MutationProbability  = 0.5f;
    var sw = System.Diagnostics.Stopwatch.StartNew();
    ga.Start();
    sw.Stop();
    double obj = -ga.BestChromosome.Fitness.Value;
    Console.WriteLine($"  {name,-12} {obj,-14:F4} {sw.Elapsed.TotalMilliseconds,-8:F0} ms");
    return obj;
}

Console.WriteLine("GeneticSharp (UniformCrossover + FlipBit, dim=10, 50 ind x 200 gen, seed 42) :");
Console.WriteLine($"  {"Fonction",-12} {"Objectif",-14} {"Temps",-8}");
Console.WriteLine(new string('-', 38));
