    QE("A","D",2), QE("D","A",2),  QE("B","E",1), QE("E","B",1),
    QE("C","F",5), QE("F","C",5),  QE("D","E",6), QE("E","D",6),
    QE("E","F",2), QE("F","E",2)
}.ToBidirectionalGraph<string, STaggedEdge<string,double>>();

