var dijkstra = new DijkstraShortestPathAlgorithm<string, STaggedEdge<string,double>>(qg, e => e.Tag);
// Observateur canonique : enregistre l'arbre des predecesseurs pendant le calcul (condition
// d'optimalite GetDistance(u) + poids(u, v) = GetDistance(v) encapsulee — parite tranche 1 §3).
var rec = new VertexPredecessorRecorderObserver<string, STaggedEdge<string, double>>();
