// Reconstruction du chemin A -> F via l'observateur (API Attach + TryGetPath, aretes ->
// projection en sommets) — parite avec la tranche 1, section 3.
string Retrace(string target)
{
    if (target == "A") return "A";
    if (!rec.TryGetPath(target, out var aretes)) return target;
    return string.Join(" -> ", new[] { aretes.First().Source }.Concat(aretes.Select(a => a.Target)));
}
