// Problème de Transport — PL continue (GLOP). Twin .NET de §4 (notebook Python/PuLP).
var solverT = Solver.CreateSolver("GLOP");

// 3 usines (sources) × 4 magasins (destinations)
string[] usines = { "U1", "U2", "U3" };
string[] magasins = { "M1", "M2", "M3", "M4" };
double[,] couts = {
    { 2, 3, 1, 4 },   // U1 -> M1..M4
    { 5, 2, 3, 2 },   // U2
    { 3, 4, 2, 1 },   // U3
};
double[] capacites = { 100, 150, 200 };     // offre par usine
double[] demandes  = { 80, 120, 100, 150 }; // demande par magasin
int m = usines.Length, n = magasins.Length;

// Variables x_ij >= 0 : quantité transportée de l'usine i vers le magasin j
var x = new Variable[m, n];
for (int i = 0; i < m; i++)
    for (int j = 0; j < n; j++)
        x[i, j] = solverT.MakeNumVar(0.0, double.PositiveInfinity, $"x_{usines[i]}_{magasins[j]}");

// Offre : Σ_j x_ij <= capacites[i]
for (int i = 0; i < m; i++)
{
    var c = solverT.MakeConstraint(double.NegativeInfinity, capacites[i], $"Offre_{usines[i]}");
    for (int j = 0; j < n; j++) c.SetCoefficient(x[i, j], 1.0);
}

// Demande : Σ_i x_ij >= demandes[j]
for (int j = 0; j < n; j++)
{
    var c = solverT.MakeConstraint(demandes[j], double.PositiveInfinity, $"Demande_{magasins[j]}");
    for (int i = 0; i < m; i++) c.SetCoefficient(x[i, j], 1.0);
}

// Objectif : min Σ c_ij x_ij. Accumulation depuis le 1er terme (OrTools 9.11 sans Sum() statique, cf. §5 sac à dos).
LinearExpr coutTotal = couts[0, 0] * x[0, 0];
for (int i = 0; i < m; i++)
    for (int j = 0; j < n; j++)
        if (!(i == 0 && j == 0))
            coutTotal += couts[i, j] * x[i, j];
solverT.Minimize(coutTotal);

var statutT = solverT.Solve();
var sb = new System.Text.StringBuilder();
sb.AppendLine("=== Problème de Transport (GLOP) ===");
sb.AppendLine($"Statut           : {statutT}");
sb.AppendLine($"Coût total min.  : {solverT.Objective().Value():F0} €");
sb.AppendLine();
sb.AppendLine("Matrice des flux optimaux (lignes = usines, colonnes = magasins) :");
sb.AppendLine("       M1   M2   M3   M4  | expédié / capacité");
for (int i = 0; i < m; i++)
{
    double expedie = 0;
    var ligne = $"  {usines[i]} | ";
    for (int j = 0; j < n; j++) { ligne += $"{x[i, j].SolutionValue(),4:F0} "; expedie += x[i, j].SolutionValue(); }
    ligne += $"| {expedie,3:F0} / {capacites[i]}";
    sb.AppendLine(ligne);
}
double totalCap = capacites.Sum();
double totalDem = demandes.Sum();
sb.AppendLine($"  Demande reçue  : {string.Join("  ", demandes.Select(d => $"{d,3:F0}"))}  (total {totalDem:F0})");
sb.AppendLine();
sb.AppendLine($"Total capacité = {totalCap:F0}, total demande = {totalDem:F0} → problème {(totalCap == totalDem ? "équilibré" : "déséquilibré")}.");
sb.ToString().Display();

// Transport multi-dépôts — PL continue (GLOP). Twin .NET de l'Exemple guide 4 (Python/PuLP).
var solverMD = Solver.CreateSolver("GLOP");

string[] depots = { "D1", "D2" };
string[] clients = { "C1", "C2", "C3" };
double[,] coutsMD = {
    { 4, 6, 3 },   // D1 -> C1,C2,C3
    { 5, 2, 7 },   // D2
};
double[] capacitesMD = { 50, 40 };     // offre par dépôt
double[] demandesMD  = { 30, 25, 35 }; // demande par client
int mMD = depots.Length, nMD = clients.Length;

// Variables x_ij >= 0 : quantité livrée du dépôt i au client j
var xMD = new Variable[mMD, nMD];
for (int i = 0; i < mMD; i++)
    for (int j = 0; j < nMD; j++)
        xMD[i, j] = solverMD.MakeNumVar(0.0, double.PositiveInfinity, $"x_{depots[i]}_{clients[j]}");

// Offre : Σ_j x_ij <= capacites[i]
for (int i = 0; i < mMD; i++)
{
    var c = solverMD.MakeConstraint(double.NegativeInfinity, capacitesMD[i], $"Offre_{depots[i]}");
    for (int j = 0; j < nMD; j++) c.SetCoefficient(xMD[i, j], 1.0);
}
// Demande : Σ_i x_ij >= demandes[j]
for (int j = 0; j < nMD; j++)
{
    var c = solverMD.MakeConstraint(demandesMD[j], double.PositiveInfinity, $"Demande_{clients[j]}");
    for (int i = 0; i < mMD; i++) c.SetCoefficient(xMD[i, j], 1.0);
}

// Objectif : min Σ c_ij x_ij (accumulation depuis le 1er terme, OrTools 9.11 sans Sum() statique).
LinearExpr coutMD = coutsMD[0, 0] * xMD[0, 0];
for (int i = 0; i < mMD; i++)
    for (int j = 0; j < nMD; j++)
        if (!(i == 0 && j == 0))
            coutMD += coutsMD[i, j] * xMD[i, j];
solverMD.Minimize(coutMD);

var statutMD = solverMD.Solve();
var sbMD = new System.Text.StringBuilder();
sbMD.AppendLine("=== Transport multi-dépôts équilibré (GLOP) ===");
sbMD.AppendLine($"Statut           : {statutMD}");
sbMD.AppendLine($"Coût total min.  : {solverMD.Objective().Value():F0} €");
sbMD.AppendLine();
sbMD.AppendLine("Flux optimaux (lignes = dépôts, colonnes = clients) :");
sbMD.AppendLine("       C1   C2   C3  | expédié / capacité");
for (int i = 0; i < mMD; i++)
{
    double expedie = 0;
    var ligne = $"  {depots[i]} | ";
    for (int j = 0; j < nMD; j++) { ligne += $"{xMD[i, j].SolutionValue(),4:F0} "; expedie += xMD[i, j].SolutionValue(); }
    ligne += $"| {expedie,3:F0} / {capacitesMD[i]}";
    sbMD.AppendLine(ligne);
}
sbMD.AppendLine($"  Demande reçue  : {string.Join("  ", demandesMD.Select(d => $"{d,3:F0}"))}  (total {demandesMD.Sum():F0})");
sbMD.ToString().Display();

