// A* via QuikGraph sur Lille -> Toulouse (meme experience que cell 11 du jumeau from-scratch).
// Heuristique : meme Haversine(a, b) que cell 4, rebrindee sur l'objectif Toulouse.
// La convention QuikGraph pour l'heuristique est : h(TV vertex) -> double.
var astarQG = new AStarShortestPathAlgorithm<string, STaggedEdge<string, double>>(
    villesQG,
    e => e.Tag,
    v => Haversine(v, "Toulouse"));
// Observateur canonique : reconstruit le chemin depuis l'arbre des predecesseurs construit
// par A* (meme API Attach + TryGetPath que Dijkstra — l'algorithme implante
// ITreeBuilderAlgorithm). Condition d'optimalite encapsulee : GetDistance(u) + poids(u,v) = GetDistance(v).
var rec = new VertexPredecessorRecorderObserver<string, STaggedEdge<string, double>>();
rec.Attach(astarQG);

astarQG.Compute("Lille");

double distLilleToulouse = astarQG.GetDistance("Toulouse");
Console.WriteLine($"AStar QuikGraph Lille -> Toulouse : {distLilleToulouse:F0} km");

// Reconstruction du chemin via TryGetPath (aretes -> projection en sommets).
string cheminQG = rec.TryGetPath("Toulouse", out var aretesQG)
    ? string.Join(" -> ", new[] { aretesQG.First().Source }.Concat(aretesQG.Select(a => a.Target)))
    : "Lille";
Console.WriteLine($"Chemin : {cheminQG}");

