double gQuikGraph = distLilleToulouse;
bool eqCout = Math.Abs(gFromScratch - gQuikGraph) < 1e-6;
Console.WriteLine($"{"Cout g (km)",-22} {gFromScratch,18:F0} {gQuikGraph,18:F0} {(eqCout ? "OK" : "DIFF"),10}");

// Chemin
