# Calcul du front de Pareto (minimiser temps, maximiser qualite)
pareto_points = []
for _, row in agg.iterrows():
    pareto_points.append({
        "paradigm": row["paradigm"],
        "time": row["avg_time"],
        "quality": row["avg_quality"],
    })

def is_dominated(p, others):
    return any(o["time"] <= p["time"] and o["quality"] >= p["quality"] and o != p
               for o in others)

pareto_front = [p for p in pareto_points if not is_dominated(p, pareto_points)]
print(f"\nFront de Pareto ({len(pareto_front)}/{len(pareto_points)} non-domines) :")
for p in sorted(pareto_front, key=lambda x: x["time"]):
    print(f"  {p['paradigm']:22s} : t={p['time']*1000:7.2f}ms, qualite={p['quality']:.3f}")

WIDTH, HEIGHT = 7, 6
FOUR = 4


class ConnectFour:
    """Plateau 7x6 avec gravite, stocke par colonnes (grille[col][ligne])."""

    def __init__(self):
        self.grid = [[" "] * HEIGHT for _ in range(WIDTH)]
        self.heights = [0] * WIDTH
        self.moves = 0

    def legal_moves(self):
        return [c for c in range(WIDTH) if self.heights[c] < HEIGHT]

    def play(self, col, player):
        row = self.heights[col]
        if row >= HEIGHT:
            raise ValueError(f"colonne pleine : {col}")
        self.grid[col][row] = player
        self.heights[col] += 1
        self.moves += 1
        return row

    def undo(self, col):
        self.heights[col] -= 1
        row = self.heights[col]
        self.grid[col][row] = " "
        self.moves -= 1

    def is_win_at(self, col, row, player):
        """Alignement passant par (col, row) uniquement : cout constant par coup."""
        for dc, dr in ((1, 0), (0, 1), (1, 1), (1, -1)):
            count = 1
            for s in (1, -1):
                k = 1
                while True:
                    cc, rr = col + dc * k * s, row + dr * k * s
                    if not (0 <= cc < WIDTH and 0 <= rr < HEIGHT) or self.grid[cc][rr] != player:
                        break
                    count += 1
                    k += 1
            if count >= FOUR:
                return True
        return False

    def is_win(self, player):
        """Balayage complet (verification ponctuelle, hors boucles chaudes)."""
        for c in range(WIDTH):
            for r in range(HEIGHT):
                if self.grid[c][r] == player and self.is_win_at(c, r, player):
                    return True
        return False

    def is_full(self):
        return self.moves == WIDTH * HEIGHT

    def heuristique(self, player):
        """Somme des scores des fenetres de 4 : 1000 pour un alignement complet,
        scores intermediaires pour 2 ou 3 pions menacants, symetrique pour l'adversaire."""
        adv = "O" if player == "X" else "X"
        gains = {1: 1, 2: 10, 3: 50, 4: 1000}
        total = 0
        for c in range(WIDTH):
            for r in range(HEIGHT):
                for dc, dr in ((1, 0), (0, 1), (1, 1), (1, -1)):
                    cells_w = []
                    ok = True
                    for k in range(FOUR):
                        cc, rr = c + dc * k, r + dr * k
                        if not (0 <= cc < WIDTH and 0 <= rr < HEIGHT):
                            ok = False
                            break
                        cells_w.append(self.grid[cc][rr])
                    if not ok:
                        continue
                    mine, his = cells_w.count(player), cells_w.count(adv)
                    if mine and not his:
                        total += gains[mine]
                    elif his and not mine:
                        total -= gains[his]
        return total


# Verification du moteur : alignement horizontal de X en ligne 0 (colonnes 3-6)
