class NodeCounter:
    def __init__(self):
        self.nodes = 0

    def visit(self):
        self.nodes += 1


def _current_player(board):
    return "X" if board.moves % 2 == 0 else "O"


def minimax(board, depth, player, counter):
    """Minimax exhaustif a profondeur fixee (negamax). Retourne (score, colonne)."""
    counter.visit()
    if depth == 0 or board.is_full():
        return board.heuristique(player), None
    adv = "O" if player == "X" else "X"
    best_score, best_col = -float("inf"), None
    for col in board.legal_moves():
        row = board.play(col, player)
        if board.is_win_at(col, row, player):
            score = 100000 + depth       # gagner MAINTENANT : plus tot (depth elevee) = mieux
        else:
            score, _ = minimax(board, depth - 1, adv, counter)
            score = -score
        board.undo(col)
        if score > best_score:
            best_score, best_col = score, col
    return best_score, best_col


def alphabeta(board, depth, player, counter, alpha=-float("inf"), beta=float("inf")):
    """Meme arbre que minimax, avec elagage alpha-beta (nega-alpha)."""
    counter.visit()
    if depth == 0 or board.is_full():
        return board.heuristique(player), None
    adv = "O" if player == "X" else "X"
    best_score, best_col = -float("inf"), None
    for col in board.legal_moves():
        row = board.play(col, player)
        if board.is_win_at(col, row, player):
            score = 100000 + depth
        else:
            score, _ = alphabeta(board, depth - 1, adv, counter, -beta, -alpha)
            score = -score
        board.undo(col)
        if score > best_score:
            best_score, best_col = score, col
        alpha = max(alpha, best_score)
        if alpha >= beta:
            break                          # branche elaguee : jamais visitee, jamais comptee
    return best_score, best_col


class MCTSNode:
    __slots__ = ("parent", "col", "player", "children", "wins", "visits", "untried")

    def __init__(self, parent, col, player, legal):
        self.parent, self.col, self.player = parent, col, player
        self.children, self.untried = [], list(legal)
        self.wins = self.visits = 0

    def ucb(self, c=1.4):
        if self.visits == 0:
            return float("inf")
        return self.wins / self.visits + c * math.sqrt(math.log(self.parent.visits) / self.visits)


def mcts(board, iterations, counter, rng):
    """Monte-Carlo Tree Search : selection UCB1, expansion, rollout aleatoire, backprop.
    Retourne (visites du meilleur coup, colonne)."""
    root_player = _current_player(board)
    root = MCTSNode(None, None, root_player, board.legal_moves())
    for _ in range(iterations):
        node, state = root, board
        path_cols = []
        while not node.untried and node.children:
            node = max(node.children, key=MCTSNode.ucb)
            state.play(node.col, node.player)
            path_cols.append(node.col)
        if node.untried:
            col = node.untried.pop(rng.randrange(len(node.untried)))
            nxt = "O" if node.player == "X" else "X"
            state.play(col, node.player)
            path_cols.append(col)
            node = MCTSNode(node, col, nxt, state.legal_moves())
            node.parent.children.append(node)
        counter.visit()
        # simulation sur une copie : le plateau de jeu reste intact
        roll = ConnectFour()
        roll.grid = [c[:] for c in state.grid]
        roll.heights = list(state.heights)
        roll.moves = state.moves
        sim = _current_player(roll)
        winner = None
        while True:
            col_r = rng.choice(roll.legal_moves())
            row_r = roll.play(col_r, sim)
            if roll.is_win_at(col_r, row_r, sim):
                winner = sim
                break
            if roll.is_full():
                winner = None
                break
            sim = "O" if sim == "X" else "X"
        while node is not None:
            node.visits += 1
            if winner is None:
                node.wins += 0.5
            elif winner == node.player:
                node.wins += 1
            node = node.parent
        for c_ in reversed(path_cols):
            state.undo(c_)
    best = max(root.children, key=lambda ch: ch.visits)
    return best.visits, best.col


def random_move(board, rng):
    return rng.choice(board.legal_moves())

def instance_knapsack(n, seed, ratio_poids=0.5):
    """Instance 0/1 synthetique : n objets, capacite = ratio * somme poids."""
    rng = random.Random(seed)
    poids = [rng.randint(10, 100) for _ in range(n)]
    valeurs = [poids[i] + rng.randint(-5, 20) for i in range(n)]  # correlation valeur/poids
    capacite = int(ratio_poids * sum(poids))
    return poids, valeurs, capacite

def borne_lp(poids, valeurs, capacite):
    """Relaxation fractionnaire (greedy densite) : majorant de l'optimum 0/1."""
    ordre = sorted(range(len(poids)), key=lambda i: valeurs[i] / poids[i], reverse=True)
    reste, total = capacite, 0
    for i in ordre:
        pris = min(poids[i], reste)
        total += valeurs[i] * pris / poids[i]
        reste -= pris
        if reste == 0:
            break
    return total

def dp_exact(poids, valeurs, capacite):
    """Optimum 0/1 exact par programmation dynamique (temoin de verite)."""
    best = [0] * (capacite + 1)
    for p, v in zip(poids, valeurs):
        for c in range(capacite, p - 1, -1):
            if best[c - p] + v > best[c]:
                best[c] = best[c - p] + v
    return best[capacite]

def admissible(x, poids, capacite):
    return sum(p for p, xi in zip(poids, x) if xi) <= capacite

def valeur(x, valeurs):
    return sum(v for v, xi in zip(valeurs, x) if xi)

def descente_sous_budget(x0, poids, valeurs, capacite, budget, collect=True):
    """Hill-climbing a stricte amelioration, plafonne a `budget` evaluations.

    Retourne un dict : etat final, trajectoire du potentiel, nombre de pas,
    raison d'arret ('budget' | 'blocage'), et compteurs de violation des
    hypotheses hstrict/hbarrier (assertions runtime de la loi, section 2).
    """
    lp = borne_lp(poids, valeurs, capacite)
    x = list(x0)
    phi = -valeur(x, valeurs)          # potentiel : decroitre = s'ameliorer
    trajectoire = [phi] if collect else []
    hstrict_viol, hbarrier_viol = 0, 0
    evaluations, pas = 0, 0
    ameliorant_final = None
    while evaluations < budget:
        best_delta, best_i = 0, None
        for i in range(len(x)):
            if evaluations >= budget:
                break
            y = list(x); y[i] = 1 - y[i]
            if not admissible(y, poids, capacite):
                evaluations += 1
                continue
            evaluations += 1
            d = valeur(y, valeurs) - valeur(x, valeurs)
            if d > best_delta:
                best_delta, best_i = d, i
        if best_i is None:
            ameliorant_final = False   # aucun voisin ameliorant : blocage
            break
        y = list(x); y[best_i] = 1 - y[best_i]
        phi_new = -valeur(y, valeurs)
        if phi_new >= phi:             # hstrict : mouvement accepté doit decroitre strictement
            hstrict_viol += 1
        if -phi_new > lp + 1e-9:       # hbarrier : confinement sous le majorant LP
            hbarrier_viol += 1
        x, phi = y, phi_new
        pas += 1
        if collect:
            trajectoire.append(phi)
    else:
        ameliorant_final = None        # budget epuise avant balayage complet du voisinage
    if ameliorant_final is None:
        # le dernier balayage incomplet peut cacher un ameliorant : le noter honnetement
        raison = 'budget'
    else:
        raison = 'blocage'
    return {'x': x, 'valeur': -phi, 'trajectoire': trajectoire, 'pas': pas,
            'evaluations': evaluations, 'raison': raison,
            'hstrict_viol': hstrict_viol, 'hbarrier_viol': hbarrier_viol,
            'lp': lp}

import heapq
from collections import deque
import matplotlib.pyplot as plt
import numpy as np

W, H = 14, 10
PLAIN, FOREST, SWAMP = 1, 3, 8
COST = [[FOREST] * W for _ in range(H)]
for r in range(H):                       # corridor serpentin en plaine
    COST[r][1] = PLAIN
for c in range(1, W - 1):
    COST[H - 2][c] = PLAIN
for r in range(H - 2, -1, -1):
    COST[r][W - 2] = PLAIN
for i in range(2, min(W, H) - 1):        # marais sur la diagonale directe
    COST[i][i + 2] = SWAMP
    if i + 3 < W:
        COST[i][i + 3] = SWAMP
COST[0][0], COST[H - 1][W - 1] = PLAIN, PLAIN
START, GOAL = (0, 0), (H - 1, W - 1)

fig, ax = plt.subplots(figsize=(7.2, 5.0))
ax.imshow(np.array(COST), cmap="YlGn", vmin=0, vmax=9)
for r in range(H):
    for c in range(W):
        ax.text(c, r, COST[r][c], ha="center", va="center", fontsize=8)
ax.plot(START[1], START[0], "ks", markersize=12, label="depart")
ax.plot(GOAL[1], GOAL[0], "k*", markersize=14, label="arrivee")
